   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1020;
       --bg-accent: #151c35;
       --panel: rgba(16, 24, 48, 0.88);
       --panel-strong: rgba(20, 30, 59, 0.96);
       --text: #ecf2ff;
