     .example {
       border: 1px solid var(--line);
       border-radius: var(--radius);
       background: linear-gradient(180deg, var(--panel), var(--panel-strong));
       box-shadow: var(--shadow);
       overflow: hidden;
     }

     .example h2 {
       margin: 0;
       font-size: 1.1rem;
